export async function loadServices(){const embedded=typeof document!=='undefined'&&document.querySelector('[data-service-bootstrap]');if(embedded){try{const data=JSON.parse(embedded.textContent);settings=data.settings;projects=data.projects;catalogProducts=data.products;return;}catch{}}try{const src=typeof document!=='undefined'&&document.querySelector('[data-service-bootstrap-src]')?.dataset.serviceBootstrapSrc;const boot=src?await fetch(src):{ok:false};if(boot.ok){const data=await boot.json();settings=data.settings;projects=data.projects;catalogProducts=data.products;return;}}catch{}try{const [a,b,c]=await Promise.all([fetch('/api/service-settings'),fetch('/api/projects'),fetch('/api/products')]);if(a.ok)settings=await a.json();if(b.ok)projects=(await b.json()).projects;if(c.ok)catalogProducts=(await c.json()).products;}catch{}if(!document.querySelector('[href="/services.css"]')){const l=document.createElement('link');l.rel='stylesheet';l.href='/services.css';document.head.append(l);}}
