function wallGuide(config=settings){const settings=config;const steps=[['measure','Measure','Measure the widest and tallest points of the wall in inches and add the trimming allowance.'],['prep','Prepare the wall','Clean, dry and smooth. Let fresh paint cure fully (about 3 weeks) before installing.'],['align','Hang panel 1 straight','Draw a plumb line and align the first panel to it — every other panel follows it.'],['smooth','Smooth from the centre','Work out bubbles from the centre outward with a smoothing tool.'],['trim','Trim the edges','Check the pattern match, then trim at the ceiling, floor and corners with a sharp blade.'],['care','Care','Wipe with a soft damp cloth. Removable panels peel off; test adhesion on painted walls first.']];return section(`<span class="eyebrow">Installation guide</span><h2 class="d2">How to install your wallpaper</h2><ol class="wall-steps">${steps.map(([k,h,t],i)=>`<li><span class="wall-step-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${WALL_ICONS[k]}</svg></span><b>${i+1}. ${h}</b><p>${t}</p></li>`).join('')}</ol>${settings.wallGuide?`<details class="wall-guide-more"><summary>Full preparation notes</summary><div class="terms-prose">${esc(settings.wallGuide)}</div></details>`:''}<p class="small">Prefer not to DIY? Add professional installation ($3 / sq ft) when you order.</p>`,'alt');}
