export async function mountEnhancements(root,path){const container=root.querySelector('.page-enter');if(!container)return;batchPages(root,path,settings,projects,catalogProducts);
for(const im of root.querySelectorAll('img')){const source=im.getAttribute('src')||'',prints=[['pr-bc','business-cards'],['pr-flyer','flyers'],['pr-postcard','postcards'],['pr-brochure','brochures'],['pr-doorhanger','door-hangers']].find(([prefix])=>source.includes('/satin/img/'+prefix));if(prints){im.closest('picture')?.querySelectorAll('source').forEach(x=>x.remove());im.removeAttribute('srcset');im.src='/satin/img/print-'+prints[1]+'.png';}const n=im.getAttribute('src')?.match(/\/satin\/img\/([^/]+?)(?:-\d+)?\.(?:jpg|webp)$/)?.[1];if(n&&transparentImages.includes(n)){im.closest('picture')?.querySelectorAll('source').forEach(s=>s.remove());im.removeAttribute('srcset');im.src='/satin/img/'+n+'.png';const art=im.closest('.art');if(art)art.style.background='#fff';}}
if(path.startsWith('/print-shop')&&root.querySelector('a.card[href]')){try{const r=await fetch('/api/rules/previews'),v=await r.json();if(r.ok&&root.isConnected)for(const card of root.querySelectorAll('a.card[href]')){const url=new URL(card.href,location.origin),canonical=url.pathname.replace(/^\/satin\/(fa|fr|es)(?=\/|$)/,'/satin').replace(/\/$/,'');const p=catalogProducts.find(p=>p.path===canonical&&p.ruleId.startsWith('print-'));if(!p)continue;const price=v.previews.find(q=>q.id===p.ruleId),amount=card.querySelector('.price');if(price&&amount)amount.textContent=price.subtotal?'From '+new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD'}).format(price.subtotal/100)+' / '+price.quantity.toLocaleString('en-CA'):'Price on request';if(card.querySelector('h3'))card.querySelector('h3').textContent=p.name;if(p.description&&card.querySelector('p'))card.querySelector('p').textContent=p.description;if(p.images?.[0]){const art=card.querySelector('.art');if(art)art.innerHTML=image(p.images[0],p.name);}}}catch{}}
if(path.startsWith('/vehicle-wraps/commercial/')||path.startsWith('/vehicle-wraps/estimator/')){const slug=path.split('/').at(-1),vehicle=/suv/.test(slug)?'SUV':/mini/.test(slug)?'Mini Van':/van|sprinter|transit/.test(slug)?'Van':/truck|pickup/.test(slug)?'Truck':/trailer/.test(slug)?'Trailer':/sedan/.test(slug)?'Sedan':'';const rows=projects.filter(p=>p.category==='commercial'&&(!vehicle||p.vehicle===vehicle)).slice(0,12);if(rows.length)container.insertAdjacentHTML('beforeend',section(`<div class="section-top"><div><span class="eyebrow">Recent projects</span><h2 class="d2">${vehicle||'Vehicle'} wraps in the real world.</h2></div><a class="btn ghost" href="/satin/portfolio/commercial/?vehicle=${encodeURIComponent(vehicle)}">Our Work ↗</a></div><div class="project-slider" tabindex="0" aria-label="Recent projects; scroll to see more">${rows.map(p=>`<a href="/satin/portfolio/projects/${p.slug}/" class="card">${image(p.cover?.src||p.images[0].src,p.title)}<h3>${esc(p.title)}</h3><p>${p.imageCount??p.images.length} photos · View project ↗</p></a>`).join('')}</div>`));}
for(const slider of root.querySelectorAll('.project-slider')){const controls=document.createElement('div');controls.className='project-controls';controls.innerHTML='<button type="button" class="btn ghost sm" data-project-prev aria-label="Previous projects">←</button><button type="button" class="btn ghost sm" data-project-next aria-label="Next projects">→</button>';slider.before(controls);const move=direction=>{const step=(slider.firstElementChild?.getBoundingClientRect().width||300)+20;slider.scrollBy({left:direction*step,behavior:'smooth'});};controls.onclick=e=>{if(e.target.closest('[data-project-prev]'))move(-1);if(e.target.closest('[data-project-next]'))move(1);};let paused=false;slider.onmouseenter=()=>paused=true;slider.onmouseleave=()=>paused=false;slider.onfocusin=()=>paused=true;slider.onfocusout=()=>paused=false;if(!matchMedia('(prefers-reduced-motion: reduce)').matches){const timer=setInterval(()=>{if(!slider.isConnected){clearInterval(timer);return;}if(paused||document.hidden)return;if(slider.scrollLeft+slider.clientWidth>=slider.scrollWidth-5)slider.scrollTo({left:0,behavior:'smooth'});else move(1);},5500);}}
if(path==='/vehicle-wraps/color-change'){const stage=root.querySelector('[data-finish-stage]');if(stage){const split=stage.parentElement;split.innerHTML=`<div><span class="eyebrow">3M wrap finishes</span><h2 class="d2">Pick a finish.</h2><fieldset><legend>Finish</legend><div class="finish-options">${['Gloss','Matte','Satin'].map((f,i)=>`<button class="btn ghost" data-tesla-finish="${f.toLowerCase()}" aria-pressed="${i===0}">${f}</button>`).join('')}</div></fieldset><fieldset><legend>Colour</legend><div class="finish-options">${[['black','#151515'],['white','#fff'],['graphite','#555960'],['red','#b51629'],['pink','#e88ba8'],['purple','#5b2a86'],['green','#1f6b45'],['blue','#1d4ed8'],['yellow','#f2c214'],['orange','#e8620c'],['teal','#0f7c80'],['nardo','#7a7f86']].map(([c,h],i)=>`<button class="colour-choice" data-tesla-colour="${c}" aria-pressed="${i===0}"><span style="background:${h}"></span>${c==='graphite'?'Dark grey':c==='nardo'?'Nardo grey':c[0].toUpperCase()+c.slice(1)}</button>`).join('')}</div></fieldset><p data-finish-caption>Gloss · Black</p><p class="small">Illustrative preview; confirm your exact colour with a physical film sample.</p><a class="btn ghost" href="${location.pathname.replace(/color-change\/?$/,'visualizer/')}">Try all 200+ colours in the wrap visualizer →</a><div class="cc-brands"><span class="eyebrow">Films we install</span><div class="cc-logos">${[['3M','3m.svg'],['Avery Dennison','avery-dennison.png'],['KPMF','kpmf.png'],['Arlon','arlon-dark.webp'],['TeckWrap','teckwrap.png']].map(([n,f])=>`<img src="/satin/img/brands/${f}" alt="${n}" loading="lazy">`).join('')}</div></div></div><div class="tesla-stage"><img data-tesla src="/satin/img/tesla-black-gloss.png" alt="Tesla in black gloss, side view"></div>`;let colour='black',finish='gloss';split.onclick=e=>{const f=e.target.closest('[data-tesla-finish]'),c=e.target.closest('[data-tesla-colour]');if(!f&&!c)return;if(f)finish=f.dataset.teslaFinish;if(c)colour=c.dataset.teslaColour;split.querySelectorAll('[data-tesla-finish]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.teslaFinish===finish));split.querySelectorAll('[data-tesla-colour]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.teslaColour===colour));const im=split.querySelector('[data-tesla]');im.src=['black','white','graphite','red','pink'].includes(colour)?'/satin/img/tesla-'+(colour==='pink'?'red':colour)+'-'+finish+'.png':'/satin/img/tesla-'+colour+'-'+finish+'.webp';im.style.filter=colour==='pink'?'hue-rotate(330deg) saturate(.65) brightness(1.25)':'';im.alt='Tesla in '+colour+' '+finish+', side view';split.querySelector('[data-finish-caption]').textContent=finish+' · '+colour;};}}
if(path==='/vehicle-wraps'||path==='/vehicle-wraps/commercial'){container.insertAdjacentHTML('beforeend',section('<div class="tint-shortcut"><h2>Finish the look with window tint.</h2><p>Explore vehicle tint film and coverage options.</p><a class="btn" href="/satin/window-tint/vehicle/">Vehicle window tint ↗</a></div>'));}
if(path==='/vehicle-wraps/paint-protection-film'&&!root.querySelector('.ppf-brands-sec')){const pk=[...container.querySelectorAll('h2')].find(h=>/two ways to cover it/i.test(h.textContent))?.closest('section');(pk||container.firstElementChild).insertAdjacentHTML('afterend',section(`<div class="brand-strip" aria-label="PPF brands">${settings.ppfBrands.map(n=>n==='STEK'?'<img src="https://dfmm8fty2renf.cloudfront.net/wp-content/uploads/2023/06/stek-emblem-white.svg" alt="STEK">':['3M','HEXIS','XPEL'].includes(n)?`<img src="/satin/img/brands/${n.toLowerCase()}.svg" alt="${esc(n)}">`:`<span>${esc(n)}</span>`).join('')}</div><p class="small">Explore PPF brands. Our team confirms the film available for your project.</p>`,'ppf-brands-sec'));}
const apparel=root.querySelector('[data-apparel-browser]');if(apparel){const query=new URLSearchParams(location.search);const st={group:['men','women','youth','hats','totes'].includes(query.get('group'))?query.get('group'):(apparel.dataset.initialGroup||'all'),category:'all',model:'all'};const categorySelect=apparel.querySelector('[data-apparel-category]');if(categorySelect&&[...categorySelect.options].some(o=>o.value===query.get('category')))categorySelect.value=query.get('category');const fixed=apparel.dataset.fixedCategory||'';if(fixed)st.category=fixed;const press=()=>apparel.querySelectorAll('[data-apparel-k]').forEach(b=>b.setAttribute('aria-pressed',String(st[b.dataset.apparelK]===b.dataset.apparelV)));const inCat=(c,cat)=>cat==='all'||c===cat||cat==='hoodsweat'&&['hoodies','sweatshirts'].includes(c)||cat==='tops'&&['t-shirts','long-sleeves','polos','tanks'].includes(c)||cat==='workwear'&&['polos','hoodies','sweatshirts','long-sleeves'].includes(c);const filter=()=>{const category=categorySelect?categorySelect.value:st.category,q=apparel.querySelector('[data-apparel-search]').value.toLowerCase();let count=0;apparel.querySelectorAll('[data-garment-group]').forEach(card=>{card.hidden=!((st.group==='all'||card.dataset.garmentGroup===st.group)&&inCat(card.dataset.garmentCategory,category)&&(st.model==='all'||card.dataset.garmentModel===st.model)&&card.dataset.garmentName.includes(q));if(!card.hidden)count++;});apparel.querySelector('[data-apparel-count]').textContent=count?count+' products':'No products match these filters yet — ask us, we can source it.';};press();apparel.addEventListener('input',filter);apparel.addEventListener('change',filter);apparel.onclick=e=>{const b=e.target.closest('[data-apparel-k]');if(b){st[b.dataset.apparelK]=b.dataset.apparelV;press();filter();}};filter();}
if(path.startsWith('/apparel'))mountApparelPage(root);
if(path==='/window-graphics'){for(const h of root.querySelectorAll('h2,h3'))if(h.textContent.trim()==='Measure the glass')h.closest('section')?.remove();root.querySelectorAll('.art').forEach((art,i)=>{if(!art.querySelector('img')||art.querySelector('svg'))art.innerHTML=image('/satin/img/frosted-film-installation.png','Professionally installed glass graphics');});}
if(path==='/auto-detailing'){const plans=root.querySelector('.service-plans');if(plans){plans.innerHTML=settings.detailingPlans.map((p,i)=>`<article class="card detail-plan ${i===1?'featured':''}">${image(p.image,p.name)}<div class="detail-plan-body"><span class="plan-symbol">${['✧','◈','◇'][i%3]}</span><span class="eyebrow">0${i+1} · Vehicle care</span><h3>${esc(p.name)}</h3><b class="plan-price">${esc(p.price)}</b><ul>${p.features.map(f=>`<li>${esc(f)}</li>`).join('')}</ul><button class="btn ${i===1?'':'ghost'}" data-new-detail-plan="${esc(p.name)}">Choose plan</button></div></article>`).join('');const sel=root.querySelector('[name=plan]');if(sel)sel.innerHTML='<option value="">Custom selection</option>'+settings.detailingPlans.map(p=>`<option>${esc(p.name)}</option>`).join('');plans.onclick=e=>{const b=e.target.closest('[data-new-detail-plan]');if(b&&sel){sel.value=b.dataset.newDetailPlan;sel.dispatchEvent(new Event('change',{bubbles:true}));root.querySelector('#configure')?.scrollIntoView({behavior:'smooth'});}};}container.insertAdjacentHTML('beforeend',section(`<div class="split"><div><span class="eyebrow">Care beyond your visit</span><h2 class="d2">Keep that freshly detailed feeling.</h2><p class="lede">${esc(settings.detailingIntro)}</p></div><div class="terms-prose">${esc(settings.detailingAftercare)}</div></div>`,'alt'));}
const booking=root.querySelector('[data-booking]');if(booking){const time=booking.querySelector('[name=time]'),date=booking.querySelector('[name=date]');time.type='hidden';time.required=false;time.insertAdjacentHTML('afterend','<div class="booking-spots" data-spots aria-live="polite">Choose a date to see suggested times.</div>');const spots=booking.querySelector('[data-spots]');const note=document.createElement('p');note.className='booking-notice';note.textContent=settings.bookingNote;spots.parentElement.parentElement.after(note);let serial=0;date.onchange=async()=>{const n=++serial;time.value='';spots.textContent='Loading suggested times…';try{const r=await fetch('/api/booking-slots?date='+encodeURIComponent(date.value)),v=await r.json();if(n!==serial)return;if(!r.ok)throw Error(v.error);spots.innerHTML=v.slots.length?v.slots.map(t=>`<button type="button" data-time="${t}" aria-pressed="false">${t}</button>`).join(''):'No suggested times for this date. Choose another date.';}catch(e){spots.textContent='Unable to load times. Please try again.';}};spots.onclick=e=>{const b=e.target.closest('[data-time]');if(b){time.value=b.dataset.time;spots.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));}};booking.addEventListener('submit',e=>{if(!time.value){e.preventDefault();e.stopImmediatePropagation();spots.textContent='Select a date and a suggested time before submitting.';date.focus();}},{capture:true});}
}
export async function mountProductExtras(box,rule,product,getValues){if(!box.isConnected)return;const noArt=['glass-frosted-vinyl','tint-commercial','tint-vehicle'].includes(rule.id);if(noArt)box.querySelector('.rule-artwork')?.remove();const aside=box.querySelector('.rule-summary'),hasDesign=rule.fields.some(f=>f.key==='design')||rule.id==='design-services'||rule.id.startsWith('design-');
if(hasDesign){const area=document.createElement('div');area.className='terms-check';area.dataset.designTerms='';area.innerHTML=`<label><input type="checkbox" data-design-agree> I have read and agree to the <a href="/satin/design-agreement/" target="_blank" rel="noopener">Design Agreement</a>.</label>`;aside.querySelector('[data-rule-add]').before(area);}
if(rule.fields.some(f=>f.key==='install')){const area=document.createElement('div');area.className='terms-check';area.dataset.installTerms='';area.innerHTML='<label><input type="checkbox" data-install-agree> I agree to the <a href="/satin/installation-terms/" target="_blank" rel="noopener">installation terms</a>, including additional vinyl removal / cleaning at $75 per hour.</label><label>Installation details<textarea data-install-notes rows="4" maxlength="2000" placeholder="Height, access, existing vinyl, surface condition and anything else we should know"></textarea></label>';const body=aside.querySelector('.sum-body');if(body)body.append(area);else aside.querySelector('[data-rule-add]').before(area);}
const update=()=>{if(box.querySelector('[data-design-terms]'))box.querySelector('[data-design-terms]').hidden=!(getValues().design||getValues().adjust||rule.id==='design-services');if(box.querySelector('[data-install-terms]'))box.querySelector('[data-install-terms]').hidden=!getValues().install;};box.addEventListener('change',update);box.addEventListener('design-mode-change',update);update();box._terms=()=>{const values=getValues(),design=hasDesign&&(values.design||values.adjust||rule.id==='design-services'),install=values.install;if(design&&!box.querySelector('[data-design-agree]')?.checked)throw Error('Read and accept the Design Agreement to request design services.');if(install&&!box.querySelector('[data-install-agree]')?.checked)throw Error('Read and accept the installation terms.');return [...(design?['Design Agreement accepted '+new Date().toISOString()]:[]),...(install?['Installation terms accepted '+new Date().toISOString(),'Installation notes: '+box.querySelector('[data-install-notes]').value]:[])];};
if(rule.quantityKeys&&box.querySelector('.ap-config'))mountApparelProduct(box,rule,product,getValues);
if(rule.id.startsWith('print-')){const wrap=document.createElement('section');wrap.className='product-tabs';wrap.innerHTML=`<div role="tablist" aria-label="Product information">${['Details','File Prep','Reviews'].map((n,i)=>`<button role="tab" id="product-tab-${i}" aria-selected="${i===0}" aria-controls="product-panel-${i}" tabindex="${i===0?0:-1}" data-info-tab="${i}">${n}</button>`).join('')}</div><div id="product-panel-0" role="tabpanel" aria-labelledby="product-tab-0"><h3>Made for your project</h3><p class="terms-prose">${esc(product?.details||product?.description||'Choose your size, quantity and finish above. We review your artwork and confirm production details before printing.')}</p></div><div id="product-panel-1" role="tabpanel" aria-labelledby="product-tab-1" hidden><div class="prep-steps">${(product?.filePrep||settings.filePrep).split('\n').filter(Boolean).map((s,i)=>`<article><span class="prep-number">0${i+1}</span><h3>Step ${i+1}</h3><p>${esc(s.replace(/^Step \d+:\s*/,''))}</p></article>`).join('')}</div>${(product?.templates||[]).map(t=>`<a class="guide-link" href="${esc(t.url)}" target="_blank" rel="noopener">Download PDF · ${esc(t.label)} ↗</a>`).join('')}</div><div id="product-panel-2" role="tabpanel" aria-labelledby="product-tab-2" hidden><h3>Customer experiences</h3><p class="terms-prose">${esc(product?.reviews||'See what customers say about working with Satin Graphic.')}</p><a class="btn ghost" href="/satin/reviews/">Read reviews</a></div>`;box.after(wrap);mountReviews(wrap.querySelector('#product-panel-2'),rule).catch(()=>{});const activate=i=>{wrap.querySelectorAll('[role=tab]').forEach((b,n)=>{b.setAttribute('aria-selected',n===i);b.tabIndex=n===i?0:-1;});wrap.querySelectorAll('[role=tabpanel]').forEach((p,n)=>p.hidden=n!==i);};wrap.onclick=e=>{const b=e.target.closest('[data-info-tab]');if(b)activate(+b.dataset.infoTab);};wrap.onkeydown=e=>{const b=e.target.closest('[data-info-tab]');if(b&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const i=(+b.dataset.infoTab+(e.key==='ArrowRight'?1:2))%3;activate(i);wrap.querySelector('[data-info-tab="'+i+'"]').focus();}};}
if(rule.id==='wallpaper-custom')mountRoomPreview(box);
if(/^design-/.test(rule.id)&&rule.id!=='design-services'&&/\/shop\/vehicle-wrap-designs\//.test(rule.path||''))await import('/wrap-design-ui.mjs').then(m=>m.mountWrapDesign(box,rule,product,getValues)).catch(e=>console.error(e));
if(rule.id.startsWith('ppf-')){box.closest('main')?.querySelectorAll('[data-pick-ppf]').forEach(b=>b.onclick=()=>{const radio=box.querySelector('[data-rf=plan][value="'+b.dataset.pickPpf+'"]');if(radio){radio.checked=true;radio.dispatchEvent(new Event('change',{bubbles:true}));box.scrollIntoView({behavior:'smooth'});}});const f=rule.fields.find(f=>f.key==='plan');const ranges=Array.isArray(rule.priceRanges)?rule.priceRanges:[];const fmt=n=>new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD',maximumFractionDigits:0}).format(n);for(const el of box.closest('main')?.querySelectorAll('[data-ppf-price]')||[]){const rg=ranges[+el.dataset.ppfPrice];if(rg&&(rg.min||rg.max)){el.textContent=rg.min&&rg.max?fmt(rg.min)+' – '+fmt(rg.max):'From '+fmt(rg.min||rg.max);continue;}try{const r=await fetch('/api/rules/quote',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:rule.id,values:{plan:f.options[+el.dataset.ppfPrice]?.value??f.default}})}),v=await r.json();if(v.quote)el.textContent=v.quote.subtotal?'From '+new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD'}).format(v.quote.subtotal/100)+' + tax':'Price on request';}catch{}}}
}
function mountRoomPreview(box){import('./wall-preview.mjs').then(({mountWallPreview})=>mountWallPreview(box)).catch(()=>{const host=document.querySelector('[data-room-preview]');if(host)host.insertAdjacentHTML('beforeend','<p role="alert">Preview unavailable. Please reload.</p>');});}
